from __future__ import absolute_import
import time
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v26r1


class Diagnostic(v26r1.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._diagnostic_check = DiagnosticCheckPage(driver)
        self._change_bts_rnd_parameters = ChangeBtsRndParameterPage(driver)
        self._troubleshooting_scripts = TroubleshootingScriptsPage(driver, download_checker)


class DiagnosticCheckPage(v26r1.diagnostic.DiagnosticCheckPage):

    def __init__(self, driver):
        super(DiagnosticCheckPage, self).__init__(driver)
        self._view_panel = DiagnosticCheckPageViewPanel(driver)


class DiagnosticCheckPageViewPanel(v26r1.diagnostic.DiagnosticCheckPageViewPanel):

    _RADIO_CHECKPOINTS_SELECTED_ALL = ('//blocks-diagnostic-check-setup//*[label[contains(text(), "Select radio")]]'
                                       '//p-treeselect[contains(@class, "p-inputwrapper-focus")]')
    _RADIO_TREE_CHECKS_ALL = ('//*[contains(@class, "p-treeselect-items-wrapper")]'
                              '//p-treenode/li/div/div')

    _START_BUTTON = '//otx-operation-button//button[*[text()="Start"]]'
    _GET_REPORT_BUTTON = '//otx-operation-button//button[*[text()="Get Report"]]'

    def _select_radio_checkpoints(self, radio_checkpoints, timeout=60):
        radio_checkpoints_status = self.element_exists(locator=(By.XPATH, self._RADIO_CHECKPOINTS_SELECTED_ALL))
        if radio_checkpoints_status and radio_checkpoints:
            raise AttributeError("No valid radio check points.")

        if radio_checkpoints_status and not radio_checkpoints:
            return

        self.click_enabled_element((By.XPATH, self._RADIO_CHECKPOINTS), timeout)
        if not radio_checkpoints:
            self._select_all_radio_checkpoints()
        else:
            self._select_radio_checkpoints_by_input(radio_checkpoints, timeout)
        self.click_enabled_element((By.XPATH, self._RADIO_CHECKPOINTS), timeout)


class ChangeBtsRndParameterPage(v26r1.diagnostic.ChangeBtsRndParameterPage):

    def __init__(self, driver):
        super(ChangeBtsRndParameterPage, self).__init__(driver)
        self._view_panel = ChangeBtsRndParameterPageViewPanel(driver)


class ChangeBtsRndParameterPageViewPanel(v26r1.diagnostic.ChangeBtsRndParameterPageViewPanel):

    _EXECUTE = '//button/span[contains(text(), "Execute")]'
    _EXECUTE_RESULT = '//ot-instruction//span[@class="ot-text ng-star-inserted"]'
    _ONGOING = 'Ongoing'


class TroubleshootingScriptsPage(v26r1.diagnostic.TroubleshootingScriptsPage):

    def __init__(self, driver, download_checker):
        super(TroubleshootingScriptsPage, self).__init__(driver, download_checker)
        self._view_panel = TroubleshootingScriptsViewPanel(driver, download_checker)


class TroubleshootingScriptsViewPanel(v26r1.diagnostic.TroubleshootingScriptsViewPanel):

    _DETAIL_PANEL_XPATH = '//wf-panel[@aria-hidden="false"]/wf-panel-header/span/h1[text()="Details"]'
    _MIN_BUTTON_XPATH = '//wf-panel[@aria-hidden="false"]/wf-panel-header[./span/h1[text()="Details"]]//button'

    def launch_troubleshooting_script(self, script_name, cells_name, mods_name, free_text=None,
                                      script_owner_module='System module', timeout=60):

        if self.element_exists((By.XPATH, self._DETAIL_PANEL_XPATH)):
            self.click_enabled_element((By.XPATH, self._MIN_BUTTON_XPATH))
            time.sleep(1)

        self.wait_for_text_present_in_attribute(self._SCRIPT_OWNER_MODULE_CHECKED.format(script_owner_module),
                                                'class',
                                                'valid')
        self.click_enabled_element((By.XPATH, self._SCRIPT_OWNER_MODULE_XPATH.format(script_owner_module)), timeout)
        if script_name:
            self.wait_for_enable((By.XPATH, self._SCRIPT_XPATH), timeout)
            for elem in self.driver.find_elements_by_xpath(self._SCRIPT_XPATH):
                if elem.text == script_name:
                    elem.click()
                    self.wait_for_visibility_by_xpath(self._SCRIPT_TITLE.format(script_name))

        if cells_name:
            self._select_fixed_parameters(self._CELLS_DROPDOWN_BUTTON, cells_name, timeout)

        if mods_name:
            self._select_fixed_parameters(self._MODULE_MOD_MAPPING[script_owner_module], mods_name, timeout)

        if free_text:
            self.insert_text_to_enable_element((By.XPATH, self._FREE_TEXT_PARAMETERS), free_text, timeout)

        self.click_enabled_element((By.XPATH, self._LAUNCH_SCRIPT), timeout)
        return self._launch_troubleshooting_script(timeout)
